@Test
public void testReadTimeout() throws Exception {
    final AtomicBoolean completed = new AtomicBoolean(false);
    LedgerHandle writelh = bkc.createLedger(3, 3, digestType, "testPasswd".getBytes());
    String tmp = "Foobar";
