/**
 * Test that the replication worker will not shutdown on a simple ZK disconnection
 */
@Test
public void testRWZKConnectionLost() throws Exception {
    ZooKeeper zk = ZooKeeperClient.newBuilder().connectString(zkUtil.getZooKeeperConnectString()).sessionTimeoutMs(10000).build();
    try {
        ReplicationWorker rw = new ReplicationWorker(zk, baseConf, getBookie(0));
        rw.start();
        for (int i = 0; i < 10; i++) {
            if (rw.isRunning()) {
                break;
            }
            Thread.sleep(1000);
        }
        assertTrue("Replication worker should be running", rw.isRunning());
        stopZKCluster();
        // Wait for disconnection to be picked up
        for (int i = 0; i < 10; i++) {
            if (!zk.getState().isConnected()) {
                break;
            }
            Thread.sleep(1000);
        }
        assertFalse(zk.getState().isConnected());
        startZKCluster();
        assertTrue("Replication worker should still be running", rw.isRunning());
    } finally {
        zk.close();
    }
}

